using System.Linq;
using Microsoft.VisualStudio.TestTools.UnitTesting;

namespace CodeHollow.FeedReader.Tests
{
    /// <summary>
    /// Parser tests against real-world feeds (downsized to at most 10 items) captured on 2026-11-04.
    /// Expected values were extracted with an independent XML parser (Python ElementTree), not with FeedReader.
    /// </summary>
    [TestClass]
    public class RealWorldFeedsTest
    {
        private static void AssertFeed(string name, FeedType type, string title, int itemCount, string firstItemTitle, string firstItemLink, bool firstItemHasDate)
        {
            var feed = FeedReader.ReadFromFile($"Feeds/RealWorld/{name}.xml");
            var first = feed.Items.First();

            Assert.AreEqual(type, feed.Type, "type");
            Assert.AreEqual(title, feed.Title, "feed title");
            Assert.AreEqual(itemCount, feed.Items.Count, "item count");
            Assert.AreEqual(firstItemTitle, first.Title, "first item title");
            Assert.AreEqual(firstItemLink, first.Link, "first item link");
            if (firstItemHasDate)
                Assert.IsNotNull(first.PublishingDate, $"first item date not parsed: '{first.PublishingDateString}'");
        }

